import{z as s,x as A,o as E,c as p,q as t,j as i,D as e,d as o,s as l,S as n}from"./chunks/framework.C8m1ZpeB.js";const f=JSON.parse('{"title":"封装用步进器","description":"","frontmatter":{"title":"封装用步进器","date":"2026-09-08T00:00:00.000Z","section":"litho"},"headers":[],"relativePath":"litho/packaging-steppers.md","filePath":"litho/packaging-steppers.md","lastUpdated":1791063341000}'),B={name:"litho/packaging-steppers.md"};function d(h,a,D,_,c,m){const r=A("Mermaid");return E(),p("div",null,[a[2]||(a[2]=t('<h1 id="封装用步进器" tabindex="-1">封装用步进器 <a class="header-anchor" href="#封装用步进器" aria-label="Permalink to &quot;封装用步进器&quot;">​</a></h1><div class="epigraph"><p>封装步进器买的是大矩形场、长焦深和翘曲行程；NA 故意低，好让厚胶和重建晶圆活在窗口里。</p><footer>—— 对照 packaging stepper（大视场投影）与前道扫描机的规格分工</footer></div><p><a href="/litho/display-litho">上一课</a>给出米级 FPD。缺口是 IC 厂封装线仍用「像步进器的机器」，但规格对着 RDL 而不是 MMP。本课钉封装用步进器。混合键合把对准精度再收紧，留给<a href="/litho/hybrid-bonding-alignment">下一课</a>。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>Ultratech/Veeco、Canon、SUSS 一类封装投影：场可达数厘米见方，NA 低，对准行程大，适应翘曲。分辨率典型在微米。与前道 4× 扫描机比：不是同一光学合同，掩模倍率与尺寸也不同。错买高 NA 前道机去印厚胶，DOF 不够；错买封装机去印 M0，分辨率不够。</p><p><span class="marginnote">NA（数值孔径）可以想成镜头「张角」的大小：张角越大，细节分得越细，但清晰范围（焦深）越窄。封装要涂几微米厚的胶，基板还翘曲起伏，所以故意选低 NA，用分辨率换一个「厚而宽容」的清晰窗口。</span></p><p>缺口是<strong>规格对尺度</strong>，不是品牌。与 LDI 的选择：掩模步进器对重复图形产能好，直写对多品种好——对照无掩模课。</p><h3 id="重建晶圆" tabindex="-1">重建晶圆 <a class="header-anchor" href="#重建晶圆" aria-label="Permalink to &quot;重建晶圆&quot;">​</a></h3><p>Fan-out 重建后芯片位置有统计误差，步进器要对准实测格子，而不是设计直角。面板课的 die shift 在圆片重建上同样存在。</p><p><span class="marginnote">有的「封装扫描机」仍来自前道供应商的衍生平台。看规格表：场、NA、焦深、基板，不要看商标是否眼熟。</span></p>',10)),(E(),i(n,null,{default:e(()=>[l(r,{id:"mermaid-28",class:"mermaid",graph:"flowchart%20TD%0A%20%20RECON%5B%22%E9%87%8D%E6%9E%84%E5%90%8E%E6%99%B6%E5%9C%86%22%5D%20--%3E%20MEAS%5B%22%E9%80%90%E8%8A%AF%E5%AE%9E%E6%B5%8B%E4%BD%8D%E7%BD%AE%E8%AF%AF%E5%B7%AE%22%5D%0A%20%20MEAS%20--%3E%20GRID%5B%22%E7%94%9F%E6%88%90%E5%AE%9E%E6%B5%8B%E7%BD%91%E6%A0%BC%22%5D%0A%20%20GRID%20--%3E%20ALIGN%5B%22%E5%AF%B9%E5%87%86%E5%88%B0%E5%AE%9E%E6%B5%8B%E7%BD%91%E6%A0%BC%22%5D%0A%20%20ALIGN%20--%3E%20EXP%5B%22%E9%80%90%E5%9C%BA%E6%9B%9D%E5%85%89%20RDL%22%5D%0A%20%20DESIGN%5B%22%E8%AE%BE%E8%AE%A1%E7%9B%B4%E8%A7%92%E7%BD%91%E6%A0%BC%22%5D%20-.-%3E%7C%22%E5%81%87%E8%AE%BE%E6%88%90%E7%AB%8B%E6%89%8D%E5%8F%AF%E7%94%A8%22%7C%20EXP%0A%20%20EXP%20--%3E%20CHK%5B%22%E5%A5%97%E5%88%BB%E6%8A%BD%E6%A3%80%22%5D%0A%20%20CHK%20--%3E%20MEAS%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[o(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=t('<h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>选型矩阵：最小线宽、胶厚、基板、wph、套刻。与前道匹配：凸点对焊盘的套刻预算来自封装机，不是来自 EUV。工厂布局：封装机通常不在同一光刻黄光间等级，颗粒规格不同。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>低 NA → 大 DOF、低分辨率，正好厚胶。大场 → 少拼接、但畸变要在大场内控。这是投影光学的另一工作点，不是失败的高 NA。</p><p><span class="marginnote">初学者容易以为分辨率越高越好。封装线宽动辄几微米，比前道宽松百倍千倍，真正稀缺的是焦深与整场畸变控制。拿前道高 NA 机印厚胶，像用显微镜读报纸——看得细，纸一皱就失焦。</span></p>',5)),(E(),i(n,null,{default:e(()=>[l(r,{id:"mermaid-44",class:"mermaid",graph:"flowchart%20TD%0A%20%20SPEC%5B%22%E5%BE%AE%E7%B1%B3%20%2F%20%E5%8E%9A%E8%83%B6%20%2F%20%E7%BF%98%E6%9B%B2%22%5D%20--%3E%20PKG%5B%22%E5%B0%81%E8%A3%85%E6%AD%A5%E8%BF%9B%E5%99%A8%22%5D%0A%20%20SPEC2%5B%22%E7%BA%B3%E7%B1%B3%20%2F%20%E8%96%84%E8%83%B6%20%2F%20%E5%B9%B3%E7%89%87%22%5D%20--%3E%20FE%5B%22%E5%89%8D%E9%81%93%E6%89%AB%E6%8F%8F%E6%9C%BA%22%5D%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[o(" Loading... ",-1)])]),_:1})),a[4]||(a[4]=t('<h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>不给某型号 NA 表当唯一。不把所有 bump 光刻当同一机。下一课键合对准可能用红外，不一定用这台步进器。</p><p>后课默认：RDL 用大视场低 NA；下一课 Cu–Cu 键合对准是另一套精度与传感器。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>封装步进器工作点是大场、低 NA、大 DOF，服务厚胶与翘曲。</li><li>与前道机、LDI、FPD 机都不同合同。</li><li>重建晶圆要对实测格子。</li><li>出处：packaging stepper 规格分工通称。</li></ul>',5))])}const g=s(B,[["render",d]]);export{f as __pageData,g as default};
